const layers:{id:Overlay;label:string;legend:string}[]=[{id:'territory',label:'Territory',legend:'Faction colors · grey: unclaimed. Claims do not move people or close borders.'},{id:'terrain',label:'Terrain',legend:'Ocean / grassland / forest / alpine'},{id:'water',label:'Water',legend:'Dry land / retained water / flooding above 100 mm'},{id:'rain',label:'Rainfall',legend:'Dark → light · 0–100+ mm per day'},{id:'temperature',label:'Temperature',legend:'Blue: cold · red: warm · darker: extreme temperatures'},{id:'population',label:'Population',legend:'Log scale · dark: empty · light: up to one million inhabitants'},{id:'food',label:'Food reserves',legend:'Settlements only · red: empty · green: 30+ days at current demand; grey: no inhabitants'},{id:'illness',label:'Illness',legend:'Share of residents ill · green: none → red: all; grey: health inactive. Contact spread requires separate activation.'},{id:'water-quality',label:'Water quality',legend:'Game indicator · teal: clean → orange: configured concentration limit; tan: dry; grey: inactive. Active water quality scales farm output.'},{id:'deposits',label:'Surface deposits',legend:'Log scale · dark: no deposits → light orange: 1 million+ pollution units; grey: inactive.'},{id:'air',label:'Air pollution',legend:'Game units/km² · log scale · teal: clean → purple: 1,000+; grey: inactive. No damage effects.'},{id:'wind',label:'Wind',legend:'Direction TOWARD: red north, yellow-green east, cyan south, violet west. Dark: calm; grey: inactive.'},{id:'communication',label:'Connections',legend:'Green: connected · amber: isolated'}];
