function describeRead(read:Read):string {const labels={technologyKnown:`knowledge of ${read.technologyId}`,technologyProgress:`research work for ${read.technologyId}`,waterPollution:'dissolved water pollution',surfacePollution:'surface pollution',waterConcentration:'water concentration',sanitationCondition:'sanitation condition',airLoad:'air pollution load',airDensity:'air pollution density',windBearingDeg:'wind bearing',windPermille:'wind strength',temperatureC:'temperature (°C)',rainMm:'rainfall (mm)',waterMm:'standing water (mm)',vegetation:'vegetation fraction',elevationM:'elevation (m)',population:'population',foodRations:'food rations',shortageDays:'consecutive shortage days',surplusDays:'consecutive surplus days'};return `${read.sample==='neighbors-average'?'neighbor average of ':read.sample==='neighbors-min'?'neighbor minimum of ':read.sample==='neighbors-max'?'neighbor maximum of ':''}${read.source==='entity-count'?`${read.entityTypeId} count`:read.source==='entity-sum'?`${read.entityTypeId}.${read.fieldId} total`:read.source==='custom'?(world.definitions.fields.find(f=>f.id===read.fieldId)?.label??read.fieldId):labels[read.source]}`;}
function describeRule(rule:CustomRule):string {
 const conditions=rule.conditions.map(c=>`${describeRead(c.read)} ${{lt:'<',lte:'≤',eq:'=',gte:'≥',gt:'>'}[c.comparison]} ${c.value}`).join(' and ');
 const effects=rule.effects.map(e=>`${e.kind==='transfer'?'share a total of ':''}${e.entityTypeId?`each ${e.entityTypeId}.`:''}${e.fieldId} ${e.kind==='add'?'+=':e.kind==='set'?'=':'up to'} ${e.value.constant}${e.value.terms.map(t=>` + (${t.coefficient} × ${describeRead(t.read)})`).join('')}${e.value.min!==undefined?`, at least ${e.value.min}`:''}${e.value.max!==undefined?`, at most ${e.value.max}`:''}${e.kind==='transfer'?` among ${e.destination==='lower-neighbors'?'lower neighbors':'neighbors'} within available stock and capacity`:''}`).join('; ');
 return `Every ${rule.everyDays} day(s), ${rule.scope==='world'?'all zones':rule.scope==='neighbors'?`zone ${rule.tileId} and neighbors`:`zone ${rule.tileId}`}${conditions?`, when ${conditions}`:''}: ${effects}.`;
}
function describeSettlementSettings(settings:Partial<typeof DEFAULT_SETTLEMENT_SETTINGS>|Record<string,number>):string {
 const labels:Record<string,string>={capacity:'population capacity',farmRationsPerDay:'farm capacity (rations/day)',workerRationsPerDay:'worker output (rations/person/day)',shortageIntervalDays:'shortage interval (days)',growthIntervalDays:'surplus growth interval (days)',reserveDays:'reserves required for growth (days)',lossPermille:'population loss (%)',growthPermille:'population growth (%)'};
 return Object.entries(settings).map(([key,value])=>`${labels[key]??key}: ${key==='lossPermille'||key==='growthPermille'?value/10:fmt(value)}`).join('; ');
}
function describeEcologySettings(settings:NonNullable<World['soilEcology']>['settings']):string {
 const labels:Record<string,string>={farmerPopulationMax:'peak farming population',cityPopulationStart:'urban pressure begins',cityPopulationFull:'full urban pressure',rainRecovery:'rain recovery',droughtLoss:'drought loss',excessRainLoss:'heavy rain loss',heatLoss:'heat loss',coldLoss:'cold loss',floodLoss:'flood loss',farmerGain:'maximum farmer benefit',cityLoss:'maximum urban soil loss',cityVegetationLoss:'maximum urban vegetation loss'};
 return Object.entries(settings).map(([key,value])=>`${labels[key]}: ${value}`).join('; ');
}
function routeStatus(status:string):string {return ({moved:'delivered',limited:'limited by stock, reserves, target or capacity',paused:'route paused','not-due':'not scheduled today',closed:'travel closed',submerged:'endpoint submerged'} as Record<string,string>)[status]??status;}
function describeOperation(o:Operation):string {
 switch(o.kind){
  case 'knowledge-configure':return `${o.enabled?'Enable/update':'Pause'} knowledge exchange worldwide, technology version ${o.expectedVersion} → ${o.expectedVersion+1}. A communicating populated land neighbor with prior-day completed knowledge adds up to ${o.bonusPermille/10}% local research work. Local workers still leave farms and need food reserves. One source per learner, lowest zone ID; no stacking or same-day relay. Travel closures do not block messages. Known technology is retained when communication closes.`;
  case 'garrison-configure':return `Set zone ${o.tileId} garrison to ${o.target} resident slots, requiring ${o.reserveDays} reserve days plus today’s meals. Healthy home members serve before research and farming; reserved slots cannot visit or migrate. Residents eat once from settlement food. Version ${o.expectedVersion} → ${o.expectedVersion+1}. Target zero demobilizes; no combat or moving army.`;
  case 'faction-borders-configure':return `${o.enabled?'Enable/update':'Pause'} hostile border rules: travel ${o.travel?'blocked':'open'}, trade ${o.trade?'blocked':'open'}, knowledge ${o.knowledge?'blocked':'open'}. Neutral, allied, same-owner and unclaimed borders remain open; local permissions still apply. Waiting travelers consume food. Physical flows ignore borders. Registry version ${o.expectedVersion} → ${o.expectedVersion+1}.`;
  case 'faction-define':return `Create/update faction ${o.faction.label} (${o.faction.id}), color ${o.faction.color}; registry version ${o.expectedVersion} → ${o.expectedVersion+1}. Existing claims retain their faction identity; no land or inhabitants are created.`;
  case 'faction-remove':return `Remove unclaimed faction ${o.factionId} and its recorded relationships. Reject if any tile still belongs to it. Registry version ${o.expectedVersion} → ${o.expectedVersion+1}.`;
  case 'faction-claim':return o.factionId?`Assign zone ${o.tileId} to ${o.factionId}, replacing any prior owner. Preserve all inhabitants, food, health and knowledge. New claims require land; enabled border rules follow the new owner. No combat is implied.`:`Release zone ${o.tileId} to unclaimed territory; preserve all contents.`;
  case 'faction-relation':return `Record ${o.factionId} ↔ ${o.otherFactionId} as ${o.relationship}, registry version ${o.expectedVersion} → ${o.expectedVersion+1}. Enabled border rules react immediately to hostility; combat is not implemented yet.`;
  case 'technology-configure':return `${o.enabled?'Enable/update':'Pause'} research and bonuses worldwide, version ${o.expectedVersion} → ${o.expectedVersion+1}. Settlements automatically choose projects: ${o.settings.workerPermille/10}% resident worker budget; require ${o.settings.reserveDays} reserve days plus today’s meals before research. Healthy residents staying home research instead of farming. Progress and knowledge persist; existing knowledge-exchange settings are preserved.`;
  case 'technology-define':return `Define ${o.definition.label} (${o.definition.id}): ${o.definition.workRequired} base worker-days, +${o.definition.farmBonusPermille/10}% farm/worker capacity and +${(o.definition.treatmentBonusPermille??0)/10}% treatment at installed plants, starting the day after completion. Prerequisites: ${o.definition.prerequisites?.join(", ")||"none"}. All active settlements may choose it automatically. Combined bonuses cap at +100%; definitions cannot be rewritten in this milestone.`;
  case 'research-assign':return `Direct zone ${o.tileId} to research ${o.technologyId}, up to ${o.workers} healthy residents per day; protect ${o.reserveDays} reserve days plus meals. Progress survives switching projects.`;
  case 'research-pause':return `Pause research in zone ${o.tileId}; retain progress, knowledge and learned improvements.`;
  case 'research-auto':return `Return zone ${o.tileId} to automatic project selection on the next day.`;
  case 'journey-depart':return `Depart ${o.label} (${o.journeyId}): ${fmt(o.population)} inhabitants, ${fmt(o.foodRations)} rations, cargo ${o.cargo.map(c=>`${c.amount} ${c.fieldId}`).join(', ')||'none'}. Path ${o.path.join(' → ')}, ${o.daysPerHop} days per leg (${(o.path.length-1)*o.daysPerHop} days if unblocked). Debit source once on Apply. Travelers eat while moving/waiting; source shortage settings are captured. Arrival waits for open land, settlement and full capacity.`;
  case 'journey-redirect':return `Redirect ${o.journeyId} from current zone ${o.tileId} along ${o.path.join(' → ')} at ${o.daysPerHop} days/leg. Restart the current leg; partial progress is discarded. Inventory and shortage progress remain.`;
  case 'journey-provision':return `Transfer ${o.foodRations} rations from the settlement at zone ${o.tileId} to journey ${o.journeyId}. No new food is created.`;
  case 'journey-dock':return `Unload all surviving travelers, food and cargo from ${o.journeyId} into the settlement at its current zone ${o.tileId}; end the journey. Requires open land and sufficient capacity.`;
  case 'resource-route-define':return `${o.route.label} (${o.route.id}) v${o.route.version}${o.route.enabled?'':' · paused'}: zone ${o.tileId} → ${o.route.toTileId}, ${o.route.fieldId}, up to ${o.route.amount} every ${o.route.everyDays} days. Keep ${o.route.reserve} at source; destination target ${o.route.target}. Requires open travel and land at both endpoints. Existing resource rules have priority; delivered stock cannot move twice that day.`;
  case 'resource-route-remove':return `Remove route ${o.routeId} originating at zone ${o.tileId}. Stored resources remain where they are.`;
  case 'disease-contact-configure':return `${o.enabled?'Enable/update':'Pause'} contact spread worldwide, health version ${o.expectedVersion} → ${o.expectedVersion+1}. Daily rate ${o.ratePermille}/1,000 scaled by the ill share of people present; floor each group, no minimum case. Visitors return new cases home. Transit parties mix internally; arrivals join destination contacts. No same-day chain transmission. New cases cannot farm today. Requires active health tracking.`;
  case 'disease-configure':return `${o.enabled?'Enable/update':'Pause'} health effects worldwide, version ${o.expectedVersion} → ${o.expectedVersion+1}. Water exposure up to ${o.settings.waterExposurePermille/10}% of susceptible residents/day, scaled by standing-water quality. Recovery ${o.settings.recoveryPermille/10}% of ill per day; immunity loss ${o.settings.immunityLossPermille/10}% per day, minimum one when a rate is positive and people remain. Ill people cannot farm while active. Activation changes no cases immediately; polluted water can cause cases on subsequent ticks. Contact settings are preserved. No direct disease deaths; existing food shortages still apply.`;
  case 'disease-introduce':return `Make ${fmt(o.count)} susceptible inhabitants ill in zone ${o.tileId}; no people are created. Only residents are directly changed.`;
  case 'disease-treat':return `Treat ${fmt(o.count)} ill residents in zone ${o.tileId}, moving them into temporary immunity.`;
  case 'water-quality-configure':return `${o.enabled?'Enable/update':'Pause'} water quality worldwide, version ${o.expectedVersion} → ${o.expectedVersion+1}. Wash ${o.settings.washoffPermille/10}% of wet deposits/day, settle ${o.settings.settlingPermille/10}%, decay ${o.settings.decayPermille/10}%. ${o.settings.settlementWasteEnabled?`Settlements add ${o.settings.wastePerPerson} waste units per resident daily.`:'Settlement waste is disabled.'} Sanitation loses ${o.settings.shortageLossPermille/10} condition points per short-food day and recovers ${o.settings.recoveryPermille/10} on fully-fed days. Game quality reaches zero at ${o.settings.qualityLimitPerMillionL} units/million L. Activation starts clean; existing loads survive pause. Active water quality multiplies weather/soil-adjusted harvest, down to zero at the concentration limit. Illness requires separate health activation.`;
  case 'water-pollution-release':return `Add ${fmt(o.amount)} pollution units to zone ${o.tileId} ${o.pool==='water'?'water (surface deposit if dry)':'surface deposits'}. Downstream effects follow actual runoff.`;
  case 'water-pollution-cleanup':return `Remove exactly ${fmt(o.amount)} pollution units from zone ${o.tileId}, dissolved first, then surface. Sources remain configured.`;
  case 'water-pollution-source':return `Zone ${o.tileId} adds ${fmt(o.unitsPerDay)} units/day to surface deposits. Zero stops this explicit source; settlement waste and existing deposits are separate.`;
  case 'sanitation-configure':return `Zone ${o.tileId} sanitation capacity ${fmt(o.capacityPerDay)} units/day, condition ${o.conditionPermille/10}%. This sets condition immediately, including repairs. Requires a populated settlement to treat; food shortage can reduce future capacity. No construction or currency cost yet.`;
  case 'air-configure':return `${o.enabled?'Enable/update':'Pause'} world air transport, version ${o.expectedVersion} → ${o.expectedVersion+1}. Mixing ${o.settings.mixingPermille/10}% daily, removal ${o.settings.removalPermille/10}% after transport. Initial activation creates clean air and seeded winds. Pausing freezes loads and emissions; no damage to farming, vegetation or inhabitants.`;
  case 'air-release':return `${o.delta>=0?'Release':'Remove'} ${fmt(Math.abs(o.delta))} airborne pollution units in zone ${o.tileId}. Downwind consequences develop during ticks; source settings stay unchanged.`;
  case 'air-source':return `Zone ${o.tileId} emits ${fmt(o.unitsPerDay)} pollution units/day. Zero stops new emissions; existing load remains. Transport must be active to run.`;
  case 'air-wind':return `Wind in zone ${o.tileId} blows TOWARD ${o.bearingDeg}° (north 0°, east 90°), transporting up to ${o.transportPermille/10}% daily plus global mixing. Zero is calm; mixing may still spread pollution.`;
  case 'migration-configure':return `${o.enabled?'Enable/update':'Pause'} automatic relocation worldwide. Up to ${o.settings.departurePermille}/1,000 residents per departure (minimum one when positive), ${o.settings.cooldownDays}-day source cooldown, ${o.settings.daysPerHop} days to a neighboring settlement. Protect destination food coverage of ${o.settings.destinationReserveDays} days; carry up to ${o.settings.provisionDays} days of food from home. Food pressure, crowding at ${o.settings.crowdingPermille/10}% capacity, or ${o.settings.reserveImprovementDays}+ better reserve days can motivate moves. Existing journeys keep traveling if paused.`;
  case 'neighbor-visits-configure':return `${o.enabled?'Enable/update':'Pause'} routine neighbor visits worldwide. Daily budget ${o.settings.dailyPermille}/1,000 residents (minimum one when positive). Food collectors protect ${o.settings.foodReserveDays} reserve days and seek ${o.settings.foodTargetDays} days, carrying up to ${o.settings.carryRationsPerVisitor} rations each. Remaining travelers seek vacant farm jobs or explore. All return and eat at home; no per-trip approval. Travel closures block visits.`;
  case 'travel-permission':return `${o.allowed?'Open':'Close'} zone ${o.tileId} to routine visits, resource routes and migration in both directions. Food sharing, communication and existing generic stock transfers keep their own settings; travelers may wait if their next leg or arrival is blocked.`;
  case 'food-trade-configure':return `${o.enabled?'Enable/update':'Disable'} adjacent food sharing for the entire world, version ${o.expectedVersion} → ${o.expectedVersion+1}. Protect current meal plus ${o.settings.reserveDays} days of reserves; recipients seek current meal plus ${o.settings.targetDays} days. Daily limits: ${fmt(o.settings.exportPerDay)} exported and ${fmt(o.settings.importPerDay)} imported per zone, ${fmt(o.settings.edgePerDay)} per connection. Whole rations, stable zone priority, no same-day forwarding, no currency or population travel.`;
  case 'food-trade-permission':return `${o.allowed?'Open':'Close'} zone ${o.tileId} to both incoming and outgoing neighbor food sharing. Communication and custom-resource transfers are unchanged.`;
  case 'soil-ecology-configure':return `${o.enabled?'Enable/update':'Disable'} soil ecology for the entire world, version ${o.expectedVersion} → ${o.expectedVersion+1}. Fertility property: ${o.fieldId}; normalized fertility multiplies farm harvests. Settings: ${describeEcologySettings(o.settings)}. Rates are fertility percentage points/day; vegetation loss is fraction/day. Existing soil values are preserved.`;
  case 'settlement-create':return `Create ${o.label} on zone ${o.tileId}: ${fmt(o.population)} inhabitants and ${fmt(o.foodRations)} food rations. Settings: ${describeSettlementSettings(o.settings??DEFAULT_SETTLEMENT_SETTINGS)}. Activates daily food/population simulation.`;
  case 'settlement-configure':return `Settlement on zone ${o.tileId}: update rules v${o.expectedRulesVersion} → v${o.expectedRulesVersion+1}: ${describeSettlementSettings(o.settings)}${o.label?`; name ${o.label}`:''}. Existing shortage/surplus progress is retained.`;
  case 'settlement-food':return `Zone ${o.tileId}: creator ${o.deltaRations>=0?'adds':'removes'} ${fmt(Math.abs(o.deltaRations))} food rations; this is not trade.`;
  case 'settlement-population':return `Zone ${o.tileId}: set inhabitants to ${fmt(o.population)}. Resets shortage/surplus progress; this is not migration.`;
  case 'settlement-remove':return `Remove settlement on zone ${o.tileId}, discarding ${fmt(o.discardPopulation)} inhabitants and ${fmt(o.discardFoodRations)} rations.`;
  case 'entity-type-define':return `Entity type ${o.definition.label} v${o.definition.version}: ${o.definition.properties.map(f=>`${f.label} ${f.min}–${f.max} ${f.unit}, default ${f.defaultValue}`).join('; ')}. Migration: ${o.migration}; discard properties: ${o.discardProperties.join(', ')||'none'}.`;
  case 'entity-type-remove':return `Remove entity type ${o.typeId}; all instances and dependencies must be removed first.`;
  case 'entity-create':return `Create ${o.entity.label} (${o.entity.id}, type ${o.entity.typeId}) on zone ${o.tileId}: ${JSON.stringify(o.entity.properties)}; omitted properties use type defaults.`;
  case 'entity-update':return `Update ${o.entityId} on zone ${o.tileId}${o.toTileId!==undefined?`, move to zone ${o.toTileId}`:''}: ${o.label??''} ${JSON.stringify(o.properties??{})}.`;
  case 'entity-remove':return `Remove ${o.entityId} and its saved properties from zone ${o.tileId}.`;
  case 'artwork-activate':return `Activate artwork pack ${o.pack.label} v${o.pack.version}: ${o.pack.images.map(i=>i.slot).join(', ')}. ${o.pack.credit} Reveal timing is unchanged.`;
  case 'artwork-reset':return 'Return this world to the built-in painterly artwork; imported images remain available in its history.';
  case 'appearance-define':return `Appearance rule: ${o.rule.label} v${o.rule.version} · ${o.rule.scope} · priority ${o.rule.priority}${o.rule.enabled?'':' · paused'}. When ${o.rule.conditions.map(c=>`${describeRead(c.read)} ${c.comparison} ${c.value}`).join(' AND ')||'always'}: ${o.rule.style.label}, color ${o.rule.style.color}, artwork ${o.rule.style.asset}${o.rule.style.layers?.length?`, layers ${o.rule.style.layers.map(l=>`${l.asset} ${Math.round(l.opacity*100)}%`).join(" → ")}`:""}. Cosmetic only; existing reveal timing applies.`;
  case 'appearance-remove':return `Remove appearance rule ${o.ruleId}; remaining appearance rules or base terrain determine its look.`;
  case 'plugin-define':return `World plugin: ${o.definition.label} v${o.definition.version} · ${o.definition.scope} · ${o.definition.program.length} instructions · ${o.definition.stateFields.length} saved state values per tile. ${o.definition.description} State migration: ${o.migration}.${o.migration==='map'?` ${(o.stateMap??[]).map(m=>'initial' in m?`${m.key}: new initial value`:`${m.key}: old ${m.from} × ${m.scale} + ${m.offset} (${m.precision==='exact'?'reject precision loss':'round to 0.001'})`).join('; ')}. Discard old keys: ${(o.discardStateKeys??[]).join(', ')||'none'}.`:''}`;
  case 'plugin-toggle':return `${o.enabled?'Enable':'Disable'} plugin ${o.pluginId}; saved state is retained.`;
  case 'plugin-remove':return `Remove plugin ${o.pluginId} and its saved state; output properties remain.`;
  case 'rainfall':return `Zone ${o.tileId}: ${o.mmPerDay} mm rain/day`;
  case 'elevation':return `Zone ${o.tileId}: ${o.deltaM>=0?'+':''}${o.deltaM} m elevation`;
  case 'temperature':return `Zone ${o.tileId}: ${o.celsius} °C (${o.mode==='pulse'?'one-time event':'sustained'})`;
  case 'temperature-reset':return `Zone ${o.tileId}: stop sustained temperature; residual heat/cold fades`;
  case 'communication':return `Zone ${o.tileId}: communication ${o.enabled?'connected':'isolated'}. Controls both directions of enabled neighbor knowledge exchange; preserves learned knowledge and research progress.`;
  case 'field-transfer':return `Move exactly ${o.amount} ${o.fieldId} from zone ${o.tileId} to adjacent zone ${o.toTileId}; total stock is unchanged.`;
  case 'field-set':return `Zone ${o.tileId}: ${o.fieldId} = ${o.value}`;
  case 'field-define':return `World property: ${o.definition.label} (${o.definition.id}) v${o.definition.version}; ${o.definition.min}–${o.definition.max} ${o.definition.unit}; default ${o.definition.defaultValue}; ${o.definition.quantity==='stock'?'stock resource':'index'}. ${o.definition.description} ${o.transform?`Convert every existing value: old × ${o.transform.scale} + ${o.transform.offset}; ${o.transform.precision==='exact'?'reject precision loss':'round to 0.001'}. `:''}Existing values: ${o.migration==='clamp'?'clamp to new bounds':'preserve, reject if out of bounds'}.`;
  case 'field-remove':return `Remove ${o.fieldId} and its values from every zone.`;
  case 'rule-define':return `${o.rule.label} v${o.rule.version}${o.rule.enabled?'':' (paused)'}: ${describeRule(o.rule)}`;
  case 'rule-remove':return `Remove custom rule ${o.ruleId}; existing property values remain.`;
 }
}
function updateCustomLayers() {
 const select=$<HTMLSelectElement>('custom-layer');select.replaceChildren();select.hidden=!world.definitions.fields.length;
 const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='World property overlay…';select.append(placeholder);
 for(const field of world.definitions.fields){const option=document.createElement('option');option.value=`custom:${field.id}`;option.textContent=field.label;select.append(option);}
 if(globe.overlay.startsWith('custom:')) {
  if(world.definitions.fields.some(f=>`custom:${f.id}`===globe.overlay)){select.value=globe.overlay;const f=world.definitions.fields.find(f=>`custom:${f.id}`===globe.overlay)!;text('legend',`${f.label} · ${f.min}–${f.max} ${f.unit}`);}
  else {globe.overlay='terrain';text('legend','Terrain · ocean / grassland / forest / alpine');}
 }
}
$('custom-layer').onchange=()=>{const value=$<HTMLSelectElement>('custom-layer').value;if(!value)return;globe.overlay=value as Overlay;globe.update();updateCustomLayers();for(const button of Array.from($('layer-buttons').children))button.classList.remove('active');};
