 for(const operation of proposal.operations){const p=document.createElement('p');p.textContent=describeOperation(operation);container.append(p);if(operation.kind==='plugin-define'){const details=document.createElement('details'),summary=document.createElement('summary'),code=document.createElement('pre');summary.textContent='Inspect plugin program';code.textContent=JSON.stringify(operation.definition,null,2);details.append(summary,code);container.append(details);}}
 for(const t of result.tiles){if(!t.after.research&&!t.baseline.research)continue;const row=document.createElement('p');row.className='technology-preview';const describe=(r:World['tiles'][number]['research'])=>r?.projects.map(p=>`${p.technologyId}: ${p.progress} work${p.completedTick!==undefined?' learned':''}`).join(', ')||'no research';row.textContent=`Zone ${t.id} research day +5: ${describe(t.after.research)}; without change: ${describe(t.baseline.research)}. Research uses resident farm workers; new bonuses apply the day after completion.${t.after.research?.lastDay?.knowledgeWork!==undefined?` Forecast day includes ${t.after.research.lastDay.knowledgeWork} knowledge-assisted work from zone ${t.after.research.lastDay.knowledgeSource}.`:""}`;container.append(row);}
 if(result.factionPreview?.garrisons.length){const row=document.createElement('p');row.className='garrison-preview';row.textContent='Garrisons at day +5: '+result.factionPreview.garrisons.map(g=>`zone ${g.tileId}: target ${g.target}, ${g.lastDay?.workers??0} serving (${g.lastDay?.reason??'not stepped'}), ${g.reserveDays} reserve days`).join('; ')+'. Included in existing residents and meals; no extra people or food.';container.append(row);}
 if(result.factionPreview){const f=result.factionPreview,row=document.createElement('p');row.className='faction-preview';const describe=(items:typeof f.applied)=>items.map(v=>`${v.label}: ${v.zones} zones / ${fmt(v.residents)} residents`).join('; ')||'no factions';row.textContent=`Territory before: ${describe(f.before)} → Apply: ${describe(f.applied)} → day +5: ${describe(f.forecast)}. Residents exclude travelers; claims do not create people. Relations: ${f.relations.map(r=>`${r.a} / ${r.b}: ${r.relationship}`).join('; ')||'neutral by default'}. Border rules: ${f.borders?.enabled?(['travel','trade','knowledge'] as const).filter(c=>f.borders![c]).join(', ')||'no blocked channels':'inactive'}. Hostile crossings only; no combat yet.`;container.append(row);}
